<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\MorphMany;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $number
 * @property string|null $user_id
 * @property string $name
 * @property string $email
 * @property string|null $phone
 * @property string $topic
 * @property string $subject
 * @property string $message
 * @property string|null $order_id
 * @property string $status
 * @property string $priority
 * @property Carbon|null $first_response_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class SupportTicket extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'tkt';

    protected $fillable = [
        'number', 'user_id', 'name', 'email', 'phone', 'topic', 'subject', 'message', 'order_id', 'status',
        'priority', 'first_response_at',
    ];

    protected function casts(): array
    {
        return [
            'first_response_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** @return MorphMany<Media, $this> */
    public function attachments(): MorphMany
    {
        return $this->morphMany(Media::class, 'attachable')->where('collection', 'attachments')->orderBy('position');
    }
}
